Ensure your static files (like `index.ejs`) are served correctly by setting up a middleware to serve them from the `views` folder.

```javascript
// server.js
const path = require('path');

app.use(express.static(path.join(__dirname, 'views')));

app.get('/', (req, res) => {
    res.render('index');
});

